const guideItems = [
 {slug:'obd-ariza-kodu-nedir',title:'OBD arıza kodu nedir?',deck:'Beş karakterlik kodun yapısı, P/B/C/U aileleri ve “genel” ile üreticiye özgü kod farkı.',lead:'Bir OBD arıza kodu, araç kontrol ünitesinin izlediği bir sistemde beklenen koşulun dışına çıkıldığını kaydeder. Kodun kendisi genellikle arızalı parçanın adı değil, teşhis için bir yön işaretidir.',sections:[['Kod nasıl okunur?','İlk karakter sistem ailesini gösterir: P güç aktarma, B gövde, C şasi, U modüller arası iletişim. Ardından gelen rakamlar kod ailesini ve ilgili arızayı belirtir. Bir kodun kesin yorumu için aracın marka, model ve motor bilgisi de gerekebilir.'],['Genel ve üreticiye özgü kodlar','P0 gibi genel kodlar ortak OBD-II tanımlarına dayanır. P1 ve bazı diğer ailelerde üreticiye özgü anlamlar olabilir. Bu tür kodlarda internetteki genel açıklamayı araç üreticisinin dokümanıyla karşılaştırın.'],['Koddan sonraki adım','Diğer kodları ve donma karesini kaydedin. Belirtileri ve canlı verileri bir arada değerlendirip üretici test sırasını izleyin. Kodu silmek, nedeni çözmez.']]},
 {slug:'motor-ariza-lambasi',title:'Motor arıza lambası yanarsa ne yapmalı?',deck:'Sabit ve yanıp sönen motor lambasının farkı; güvenli ilk adımlar ve kod okuma.',lead:'Motor arıza lambası, kontrol sisteminin bir sorun algıladığını gösterir. Lambanın davranışı ve aracın sürüşteki hali, ne kadar hızlı hareket etmeniz gerektiğini belirler.',sections:[['Sabit yanan lamba','Araç normal çalışıyor olsa da kodu kısa süre içinde okutun. Yakıt kapağı gibi basit bir neden de olabilir; performans kaybı veya koku varsa kontrolü geciktirmeyin.'],['Yanıp sönen lamba','Yanıp sönme ciddi tekleme gibi katalizöre zarar verebilecek bir arıza göstergesi olabilir. Güvenli bir yerde durun, aracı zorlamayın ve profesyonel yardım alın.'],['İlk kontrol listesi','Kodları ve donma karesini kaydedin. Yağ basıncı, aşırı ısınma veya ciddi güç kaybı gibi başka uyarılar varsa sürüşe devam etmeyin. Kod silmek yerine nedeni araştırın.']]},
 {slug:'kod-okunduktan-sonra',title:'OBD kodu okunduktan sonra ne yapılır?',deck:'Parça değiştirmeden önce kodları, donma karesini ve canlı veriyi birlikte yorumlama rehberi.',lead:'Kod okuyucunun gösterdiği ilk satır teşhis değildir. İyi bir sıra, gereksiz parça değişimini azaltır ve onarımın gerçekten işe yarayıp yaramadığını gösterir.',sections:[['1. Veriyi sakla','Kayıtlı, bekleyen ve kalıcı kodları not alın. Donma karesi; devir, hız, yük ve sıcaklık gibi arızanın oluştuğu anı gösterebilir. Kodları bu aşamada silmeyin.'],['2. Nedeni ayır','Birden fazla kod varsa ortak nedenleri araştırın. Elektrik beslemesi, kaçak, sensör verisi ve mekanik arıza gibi ihtimalleri ölçümlerle sıraya koyun.'],['3. Onarımı doğrula','Bulguya göre onarımı yapın. Sonra aynı çalışma koşullarında yol testi ve canlı veri kontrolü yapın. Bazı OBD monitörlerinin tamamlanması birden fazla sürüş döngüsü gerektirir.']]}
];
const guideFaqs = [['Kodu silmeden önce neyi kaydetmeliyim?','Tüm kayıtlı ve bekleyen kodları, donma karesini, lambanın durumunu ve görülen belirtileri kaydedin.'],['Arıza kodu neden geri gelir?','Koda neden olan koşul sürüyorsa kontrol ünitesi aynı sorunu yeniden algılayabilir. Onarım sonrası ilgili monitörün tamamlanması gerekir.']];
const incompleteRoute='/rehber/eksik-obd-kodu/';
const incompleteBody=`<article><section class="page-hero incomplete-hero"><div class="wrap"><span class="eyebrow">EKSİK VE BELİRSİZ KODLAR</span><h1>“P97” gördün.<br><em>Bu henüz tam kod değil.</em></h1><p>P97, D218 veya yalnızca “motor arızası” yazması, kesin DTC ve parça teşhisi için yeterli değildir. Ekrandaki metni tahminle tamamlamak yerine cihazın verdiği kaydı doğrula.</p></div></section><div class="wrap incomplete-layout"><div><section><span class="section-nr">01 / FORMAT</span><h2>Tam OBD kodu nasıl görünür?</h2><p>Standart arıza kodu beş karakterlidir: P0420, C0035 veya U0100 gibi. İlk harf sistem ailesini, kalan dört karakter kodu gösterir. “P97” üç karakterdir; eksik iki karakter için herhangi bir anlam veya onarım çıkarılamaz.</p><div class="code-format"><span class="bad">P97 <small>eksik</small></span><span aria-hidden="true">→</span><span class="good">P0420 <small>tam örnek</small></span></div></section><section><span class="section-nr">02 / KAYNAK</span><h2>Gösterge mesajı mı, teşhis kodu mu?</h2><p>Araç ekranındaki bir sayı, servis mesajı veya uygulamanın kısalttığı metin doğrudan standart OBD kodu olmayabilir. Örneğin “D218” ifadesinden otomatik olarak bir DTC anlamı üretmeyiz. Hangi cihazda ve hangi ekranda göründüğünü kaydedin.</p></section><section><span class="section-nr">03 / DOĞRULAMA</span><h2>Yeniden okurken neyi kaydetmeli?</h2><ol class="step-list"><li><span>01</span><p>Teşhis cihazında kayıtlı ve bekleyen kodların tam listesini aç. Kodun ilk harfi dahil tüm karakterlerini fotoğraflayın.</p></li><li><span>02</span><p>Kodun geldiği modülü, varsa ek alt kodu, donma karesini ve lambanın davranışını not edin.</p></li><li><span>03</span><p>Yıl, marka, model, motor ve yakıt türünü ekleyin. Kod P1 veya başka üreticiye özgü ailedeyse servis verisiyle doğrulayın.</p></li></ol></section><section><span class="section-nr">04 / SONRAKİ ADIM</span><h2>Tam kodu bulduğunda</h2><p>Kodun genel anlamını dizinde arayın. Aynı anda birden fazla kod varsa hepsini birlikte inceleyin; uyarı devam ederken yalnızca kodu silmeyin.</p><div class="incomplete-actions">${cta('Tam kodu ara','/ariza-kodlari/')}${cta('Modeline göre ilerle','/araclar/',true)}</div></section></div><aside class="vehicle-source"><strong>Biçim kaynağı</strong><p>OBD DTC’nin beş karakterli yapısı ve P/B/C/U aileleri EPA teknik raporunda açıklanır. Bu sayfa bir kod listesi değil, eksik veriyi doğru toplama rehberidir.</p><a href="https://nepis.epa.gov/Exe/ZyPURL.cgi?Dockey=P100KPTW.TXT" target="_blank" rel="noopener noreferrer">EPA OBD raporu ↗</a></aside></div></article>`;
write(incompleteRoute,page({title:'P97, D218 Gibi Eksik Arıza Kodları Nasıl Okunur? | OBDKODU',description:'P97 veya D218 tam bir standart OBD arıza kodu mu? Beş karakterli DTC biçimini, gösterge mesajı farkını ve doğru kodu yeniden okuma adımlarını öğrenin.',route:incompleteRoute,body:incompleteBody,crumbs:[{name:'Rehber',path:'/rehber/'},{name:'Eksik OBD kodu',path:incompleteRoute}],graph:[{'@type':'Article',headline:'Eksik OBD kodu nasıl doğrulanır?',inLanguage:'tr-TR',mainEntityOfPage:url(incompleteRoute),publisher:{'@type':'Organization',name:'OBDKODU'}}]}));
